create table public.proactive_events (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, event_type text not null check(event_type in ('task_overdue','calendar_upcoming','career_milestone_approaching','weekly_review_due')), fingerprint text not null, source_type text, source_id uuid, severity text not null check(severity in ('critical','high','medium','low')), occurred_at timestamptz not null, effective_until timestamptz, payload jsonb not null default '{}'::jsonb, first_detected_at timestamptz not null default now(), last_detected_at timestamptz not null default now(), resolved_at timestamptz, resolution_reason text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,fingerprint));
create table public.proactive_insights (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, insight_type text not null, fingerprint text not null, severity text not null check(severity in ('critical','high','medium','low')), title text not null, description text, href text not null, effective_until timestamptz, dismissed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,fingerprint));
create table public.proactive_insight_events (insight_id uuid not null references public.proactive_insights(id) on delete cascade, event_id uuid not null references public.proactive_events(id) on delete cascade, primary key(insight_id,event_id));
alter table public.proactive_events enable row level security; alter table public.proactive_insights enable row level security; alter table public.proactive_insight_events enable row level security;
create policy "proactive_events_own" on public.proactive_events for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy "proactive_insights_own" on public.proactive_insights for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy "proactive_insight_events_own" on public.proactive_insight_events for all to authenticated using (exists(select 1 from public.proactive_insights i where i.id=insight_id and i.user_id=(select auth.uid()))) with check (exists(select 1 from public.proactive_insights i where i.id=insight_id and i.user_id=(select auth.uid())));
